import { render } from '@solidjs/web';
import { createStore, createSignal } from 'solid-js';
import { useForm } from './validation';
import './styles.css';

const usedEmails = ['johnsmith@outlook.com', 'mary@gmail.com'];
function App() {
  const { validate, formSubmit, errors } = useForm({
    errorClass: 'error-input',
  });
  const [fields, setFields] = createStore({ password: '' });
  const [submitted, setSubmitted] = createSignal(false);
  const userNameExists = async (element) => {
    const value = element.value;
    await new Promise((resolve) => setTimeout(resolve, 200));
    return usedEmails.includes(value) ? `${value} is already being used` : '';
  };
  const matchesPassword = (element) =>
    element.value === fields.password ? '' : 'Passwords must match';
  return (
    <form ref={formSubmit(() => setSubmitted(true))}>
      <h1>Sign Up</h1>
      <div class="field-block">
        <input
          name="email"
          type="email"
          placeholder="Email"
          required
          ref={validate([userNameExists])}
        />
        <span class="error-message">{errors.email}</span>
      </div>
      <div class="field-block">
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minlength="8"
          onInput={(event) =>
            setFields((draft) => {
              draft.password = event.currentTarget.value;
            })
          }
          ref={validate()}
        />
        <span class="error-message">{errors.password}</span>
      </div>
      <div class="field-block">
        <input
          name="confirmpassword"
          type="password"
          placeholder="Confirm Password"
          required
          ref={validate([matchesPassword])}
        />
        <span class="error-message">{errors.confirmpassword}</span>
      </div>
      <button type="submit">Submit</button>
      <p role="status">{submitted() && 'Form valid — ready to submit'}</p>
    </form>
  );
}

render(() => <App />, document.getElementById('app'));

import { createStore } from 'solid-js';

export function useForm({ errorClass }) {
  const [errors, setErrors] = createStore({});
  const fields = new Map();
  async function check(config) {
    const { element, validators } = config;
    const version = ++config.version;
    element.setCustomValidity('');
    if (element.checkValidity()) {
      for (const validator of validators) {
        const message = await validator(element);
        if (version !== config.version) return;
        if (message) {
          element.setCustomValidity(message);
          break;
        }
      }
    }
    const message = element.validationMessage;
    element.classList.toggle(errorClass, !!message);
    setErrors((draft) => {
      draft[element.name] = message;
    });
  }
  const validate =
    (validators = []) =>
    (element) => {
      const config = { element, validators, version: 0 };
      fields.set(element.name, config);
      element.onblur = () => {
        void check(config);
      };
      element.oninput = () => {
        config.version++;
        element.setCustomValidity('');
        element.classList.remove(errorClass);
        setErrors((draft) => {
          delete draft[element.name];
        });
      };
    };
  const formSubmit = (callback) => (form) => {
    form.noValidate = true;
    form.onsubmit = async (event) => {
      event.preventDefault();
      for (const config of fields.values()) await check(config);
      const invalid = [...fields.values()].find(
        (config) => !config.element.validity.valid,
      );
      if (invalid) invalid.element.focus();
      else callback(form);
    };
  };
  return { validate, formSubmit, errors };
}

input {
  display: inline-block;
  padding: 4px;
  margin-top: 10px;
  margin-bottom: 10px;
}
.error-message {
  color: red;
  padding: 8px;
}
.error-input {
  box-shadow: 0px 0px 2px 1px red;
}
